WITH flattened AS (SELECT id, created_at, EXPLODE_OUTER(coupon_codes) AS tag FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, tag, COUNT(*) AS cnt, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, COUNT(CASE WHEN tag = 'VIP' THEN 1 END) AS vip_count, COUNT(*) FILTER (WHERE tag = 'SPRING10') AS spring10_rows, MIN(created_at) AS first_seen, MAX(created_at) AS last_seen FROM flattened GROUP BY DATE_TRUNC('DAY', created_at), tag ORDER BY spring10_rows NULLS FIRST;
